const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const riverPoint = ee.Geometry.Point([-82.5486, 35.6000]); // Swannanoa River near Asheville, NC
  const roi = riverPoint.buffer(100); // 100m buffer

  // Function to get Sentinel-2 image for a given date window
  function getImage(startDate, endDate) {
    let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(roi)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80)); // Allow some clouds, we'll mask later
    return col.sort('CLOUDY_PIXEL_PERCENTAGE').first(); // Least cloudy
  }

  // Function to process a single date
  function processDate(dateStr, windowDays = 3) {
    const exactStart = dateStr;
    const exactEnd = ee.Date(dateStr).advance(1, 'day').format('YYYY-MM-dd');
    let img = getImage(exactStart, exactEnd);

    // If no image on exact date, widen the window
    if (ee.Image(img).bandNames().getInfo().length === 0) {
      const wideStart = ee.Date(dateStr).advance(-windowDays, 'day').format('YYYY-MM-dd');
      const wideEnd = ee.Date(dateStr).advance(windowDays, 'day').format('YYYY-MM-dd');
      img = getImage(wideStart, wideEnd);
      console.log(`${dateStr}: No image on exact date, using ±${windowDays} days window.`);
    }
    return img;
  }

  // Dates
  const date1 = '2024-08-30';
  const date2 = '2024-10-02';

  // Get images
  const img1 = processDate(date1);
  const img2 = processDate(date2);

  // Check if images exist
  const img1Bands = img1.bandNames();
  const img2Bands = img2.bandNames();
  if (img1Bands.length().getInfo() === 0 || img2Bands.length().getInfo() === 0) {
    console.log(`August 30 images: ${img1Bands.length().getInfo() ? 'Yes' : 'No'}`);
    console.log(`October 2 images: ${img2Bands.length().getInfo() ? 'Yes' : 'No'}`);
    console.log('<answer>C1</answer>');
    return;
  }

  // Function to mask clouds and extract water pixels
  function processImage(img) {
    // Mask clouds, shadows, and cirrus using SCL band
    const scl = img.select('SCL');
    // Keep only clear land (4), bare soil (5), water (6)
    // But we want only water pixels for the river, so use water class (6)
    const waterMask = scl.eq(6); // Water class
    // Cloud mask: exclude clouds (8-9), cloud shadows (3), cirrus (10)
    const cloudMask = scl.neq(3).and(scl.neq(8)).and(scl.neq(9)).and(scl.neq(10));
    const masked = img.updateMask(waterMask.and(cloudMask));
    return masked;
  }

  const processed1 = processImage(img1);
  const processed2 = processImage(img2);

  // Extract red band (B4) mean and count for water pixels
  const redBand = 'B4';
  const scale = 20; // Sentinel-2 resolution for B4 is 10m, but we use 20m to avoid mixed pixels? Actually B4 is 10m, but we can use 20m for safety.

  const stats1 = processed1.select(redBand).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: roi,
    scale: 20,
    maxPixels: 1e9
  });

  const stats2 = processed2.select(redBand).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: roi,
    scale: 20,
    maxPixels: 1e9
  });

  const mean1 = stats1.get('B4_mean');
  const count1 = stats1.get('B4_count');
  const mean2 = stats2.get('B4_mean');
  const count2 = stats2.get('B4_count');

  // Get values
  const mean1Val = mean1.getInfo();
  const count1Val = count1.getInfo();
  const mean2Val = mean2.getInfo();
  const count2Val = count2.getInfo();

  console.log(`August 30, 2024: Valid water pixels = ${count1Val}, Mean red reflectance = ${mean1Val}`);
  console.log(`October 2, 2024: Valid water pixels = ${count2Val}, Mean red reflectance = ${mean2Val}`);

  // Check for no valid pixels (C2)
  if (count1Val === 0 || count2Val === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for invalid values (C3)
  const isValid = (val) => val !== null && !isNaN(val) && isFinite(val) && val >= 0 && val <= 1;
  if (!isValid(mean1Val) || !isValid(mean2Val)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare: if October 2 is browner (higher red reflectance) than August 30
  if (mean2Val > mean1Val) {
    console.log('October 2 red reflectance is higher → browner.');
    console.log('<answer>A</answer>');
  } else {
    console.log('October 2 red reflectance is not higher → not browner.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
